-- تقييم الأداء الوظيفي: حالة سنوية معزولة لكل مدرسة\ncreate table if not exists public.school_performance_evaluation_states (\n id uuid primary key default gen_random_uuid(),\n school_id uuid not null,\n academic_year integer not null,\n data jsonb not null default '{}'::jsonb,\n created_by uuid,\n updated_by uuid,\n created_at timestamptz not null default now(),\n updated_at timestamptz not null default now(),\n unique(school_id,academic_year)\n);\ncreate index if not exists school_performance_evaluation_states_school_idx on public.school_performance_evaluation_states(school_id,academic_year);\nalter table public.school_performance_evaluation_states enable row level security;\n-- الوصول التشغيلي يتم حصراً عبر Edge Function platform-performance بعد التحقق من platform_sessions.\n